-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONTACTOS_VERSION` BEFORE UPDATE ON `FB_CONTACTOS` FOR EACH ROW
BEGIN
IF NOT (BINARY OLD.`ID_CONTACTO` <=> BINARY NEW.`ID_CONTACTO`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_IDENTIDAD_INMUTABLE'; END IF;
IF NEW.ID_CONSULTA < OLD.ID_CONSULTA OR EXISTS (SELECT 1 FROM FB_CIU_CONSULTAS_WEB WHERE ID_PERSONA=NEW.ID_PERSONA AND ID_CONSULTA>NEW.ID_CONSULTA) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ORIGEN_ANTIGUO'; END IF;
IF NOT (BINARY OLD.`ID_CONTACTO` <=> BINARY NEW.`ID_CONTACTO`) OR NOT (BINARY OLD.`ID_CONSULTA` <=> BINARY NEW.`ID_CONSULTA`) OR NOT (BINARY OLD.`TELEFONO_1` <=> BINARY NEW.`TELEFONO_1`) OR NOT (BINARY OLD.`TIPO_TELEFONO_1` <=> BINARY NEW.`TIPO_TELEFONO_1`) OR NOT (BINARY OLD.`TELEFONO_2` <=> BINARY NEW.`TELEFONO_2`) OR NOT (BINARY OLD.`TIPO_TELEFONO_2` <=> BINARY NEW.`TIPO_TELEFONO_2`) OR NOT (BINARY OLD.`TELEFONO_3` <=> BINARY NEW.`TELEFONO_3`) OR NOT (BINARY OLD.`TIPO_TELEFONO_3` <=> BINARY NEW.`TIPO_TELEFONO_3`) OR NOT (BINARY OLD.`TELEFONO_4` <=> BINARY NEW.`TELEFONO_4`) OR NOT (BINARY OLD.`TIPO_TELEFONO_4` <=> BINARY NEW.`TIPO_TELEFONO_4`) OR NOT (BINARY OLD.`TELEFONO_5` <=> BINARY NEW.`TELEFONO_5`) OR NOT (BINARY OLD.`TIPO_TELEFONO_5` <=> BINARY NEW.`TIPO_TELEFONO_5`) OR NOT (BINARY OLD.`MAIL_1` <=> BINARY NEW.`MAIL_1`) OR NOT (BINARY OLD.`MAIL_2` <=> BINARY NEW.`MAIL_2`) OR NOT (BINARY OLD.`MAIL_3` <=> BINARY NEW.`MAIL_3`) OR NOT (BINARY OLD.`MAIL_4` <=> BINARY NEW.`MAIL_4`) OR NOT (BINARY OLD.`MAIL_5` <=> BINARY NEW.`MAIL_5`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) OR NOT (BINARY OLD.`NOMBRE_COMPLETO` <=> BINARY NEW.`NOMBRE_COMPLETO`) OR NOT (BINARY OLD.`TIPO_DOCUMENTO` <=> BINARY NEW.`TIPO_DOCUMENTO`) OR NOT (BINARY OLD.`DOCUMENTO` <=> BINARY NEW.`DOCUMENTO`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) THEN
 IF NEW.USUARIO_MODIFICADOR_ID IS NULL OR CHAR_LENGTH(TRIM(NEW.USUARIO_MODIFICADOR_ID))=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ACTOR_REQUERIDO'; END IF;
 SET NEW.VERSION=OLD.VERSION+1; SET NEW.FECHA_MODIFICACION=UTC_TIMESTAMP(6);
 ELSE SET NEW.VERSION=OLD.VERSION; SET NEW.FECHA_MODIFICACION=OLD.FECHA_MODIFICACION; SET NEW.USUARIO_MODIFICADOR_ID=OLD.USUARIO_MODIFICADOR_ID; END IF;
END$$
DELIMITER ;
